import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import io from "socket.io-client";
import './DMPage.css';

const socket = io("http://localhost:5001");

const DMPage = ({ currentUser }) => {
  const navigate = useNavigate();
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [dmList, setDmList] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const messagesEndRef = useRef(null);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  useEffect(() => {
    if (currentUser?._id) {
      socket.emit("register", currentUser._id);
    }

    socket.on("receiveMessage", (message) => {
      setMessages((prev) => [...prev, message]);
    });

    socket.on("newApplication", ({ applicantId }) => {
      fetch(`/api/user/${applicantId}`)
        .then((res) => res.json())
        .then((user) => {
          setDmList((prev) => [...prev, user]);
        });
    });

    socket.on("newConversation", (conversation) => {
      console.log("📩 Received newConversation event on frontend:", conversation);
      const otherParticipant = conversation.participants.find(u => u !== currentUser._id);

      fetch(`/api/user/${otherParticipant}`)
        .then((res) => res.json())
        .then((user) => {
          setDmList((prev) => [...prev, user]);
        });
    });

    return () => {
      socket.off("receiveMessage");
      socket.off("newApplication");
      socket.off("newConversation");
    };
  }, [currentUser]);

  const handleSend = () => {
    if (newMessage.trim() && selectedUser) {
      const message = {
        sender: currentUser._id,
        receiver: selectedUser._id,
        message: newMessage,
      };
      socket.emit("sendMessage", message);
      setNewMessage('');
    }
  };

  const handleAccept = () => {
    navigate("/CreateTimeline");
  };

  return (
    <div className="dm-container">
      <div className="header">
        <img src="images/image10.png" alt="User" />
        <div className="header-right">
          <span onClick={() => navigate("/homes")}>Home</span>
          <span onClick={() => navigate("/profile")}>Profile</span>
          <span onClick={() => navigate("/ong-proj")}>Ongoing Projects</span>
          <span onClick={() => navigate("/post")}>Post a Job</span>
          <span onClick={() => navigate("/contact")}>Contact Us</span>
          <span onClick={() => navigate("/abt")}>About</span>
        </div>
      </div>

      <div className="dm-sidebar">
        <h2>Conversations</h2>
        {dmList.map((user) => (
          <div key={user._id} className="active-chat" onClick={() => setSelectedUser(user)}>
            <img src={user.profilePhoto} alt={user.name} className="user-avatar" />
            <div className="user-info">
              <h3>{user.name}</h3>
              <p>{user.role}</p>
            </div>
          </div>
        ))}
      </div>

      <div className="chat-window">
        {selectedUser ? (
          <>
            <div className="messages-container">
              {messages.map((msg, index) => (
                <div key={index} className={`message ${msg.sender === currentUser._id ? 'sent' : 'received'}`}>
                  <p>{msg.message}</p>
                </div>
              ))}
              <div ref={messagesEndRef} />
            </div>

            <div className="message-input">
              <input
                type="text"
                value={newMessage}
                onChange={(e) => setNewMessage(e.target.value)}
                placeholder="Type your message..."
                onKeyPress={(e) => e.key === 'Enter' && handleSend()}
              />
              <button onClick={handleSend}>Send</button>
            </div>
            {currentUser.role === "client" && <button onClick={handleAccept}>Accept</button>}
          </>
        ) : (
          <p>Select a user to start chatting</p>
        )}
      </div>
    </div>
  );
};

export default DMPage;
